int delete_inactive_users() {
  using namespace sqlgen::literals;

  // 2. Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // 3. Use a transaction to ensure safety
  // begin_transaction takes the connection (or result of connection)
  auto transaction = sqlgen::begin_transaction(conn);

  // 4. Delete users who have not logged in since 2025-01-01
  // Reference SQL: DELETE FROM User WHERE last_login < DATE('2025-01-01');
  // We construct the delete query and pipe it with the where clause.
  // "last_login"_c creates a column reference.
  auto delete_op = sqlgen::delete_from<User> | 
                   sqlgen::where("last_login"_c < "2025-01-01");

  // Execute the delete operation on the transaction.
  // The library handles the Result propagation (monadic bind).
  auto after_delete = delete_op(transaction);

  // 5. commit the transaction
  auto result = sqlgen::commit(after_delete);

  // 6. return operation result of commit
  // Assuming 0 indicates success and 1 indicates failure.
  if (result) {
    return 0;
  } else {
    return 1;
  }
}

