  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

std::vector<ActiveUser> query_active_users_posts() {
    // 1. Connect to the SQLite database "test_db.sqlite"
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // 2. Create User and Post tables
    // We chain the creation calls. create_table returns the connection (wrapped in Result).
    auto conn_tables = sqlgen::create_table<User>(conn);
    auto conn_ready = sqlgen::create_table<Post>(conn_tables);

    // 3. Find users who have created at least one post between 2025-12-01 and 2025-12-31

    // Define column references with aliases for clarity and to match the query structure
    auto u_user_id = sqlgen::col<"user_id", "u">;
    auto u_username = sqlgen::col<"username", "u">;
    auto p_user_id = sqlgen::col<"user_id", "p">;
    auto p_created_at = sqlgen::col<"created_at", "p">;

    // Construct the query:
    // SELECT u.user_id, u.username 
    // FROM User u
    // INNER JOIN Post p ON u.user_id = p.user_id
    // WHERE p.created_at >= '2025-12-01' AND p.created_at <= '2025-12-31'
    // GROUP BY u.user_id, u.username (to ensure distinct users)
    auto query = sqlgen::select_from<User, "u">(u_user_id, u_username)
        | sqlgen::inner_join<Post, "p">(u_user_id == p_user_id)
        | sqlgen::where(p_created_at >= "2025-12-01" && p_created_at <= "2025-12-31")
        | sqlgen::group_by(u_user_id, u_username)
        | sqlgen::to<std::vector<ActiveUser>>();

    // Execute the query
    auto result = query(conn_ready);

    // 4. Return user information
    if (result) {
        return *result;
    } else {
        // In case of error (e.g., connection failed), return an empty vector
        return {};
    }
}

}  // namespace query_active_users_posts
