  sqlgen::ForeignKey<int, Order, "order_id"> order_id;
  sqlgen::ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};


/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // 2. Create tables
  // We chain the creation to ensure dependencies are met (Customer/Product -> Order -> OrderItem)
  auto res = sqlgen::create_table<Customer>(conn);
  res = sqlgen::create_table<Product>(res);
  res = sqlgen::create_table<Order>(res);
  res = sqlgen::create_table<OrderItem>(res);

  // 3. Query the database
  // We use table aliases t1 (Customer), t2 (Order), t3 (OrderItem), t4 (Product)
  // to match the join logic.
  auto query = sqlgen::select_from<Customer, "t1">(
                   "name"_t4.as("product_name"), 
                   "order_date"_t2,
                   "quantity"_t3) |
               sqlgen::inner_join<Order, "t2">("customer_id"_t1 ==
                                               "customer_id"_t2) |
               sqlgen::inner_join<OrderItem, "t3">("order_id"_t2 ==
                                                   "order_id"_t3) |
               sqlgen::inner_join<Product, "t4">("product_id"_t3 ==
                                                 "product_id"_t4) |
               sqlgen::where("customer_id"_t1 == customer_id) |
               sqlgen::order_by("order_date"_t2.desc()) |
               sqlgen::to<std::vector<PurchaseHistory>>;

  // 4. Read and return the results
  // query(res) executes the query using the connection from the result chain.
  // We dereference the result assuming the operation is successful.
  return *query(res);
}

