#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_employee_hierarchy {

struct Employee {
  sqlgen::PrimaryKey<int> emp_id;
  std::string name;
  std::optional<int> manager_id;
};

struct EmployeeManager {
  std::string employee;
  std::optional<std::string> manager;
};

std::vector<EmployeeManager> query_employee_hierarchy() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Construct the query:
  // 1. Select from Employee (aliased as e1)
  // 2. Select e1.name as "employee" and e2.name as "manager"
  // 3. Left join Employee (aliased as e2) on e1.manager_id = e2.emp_id
  // 4. Map result to vector of EmployeeManager structs
  auto query = sqlgen::select_from<Employee, "e1">(
                   sqlgen::col<"name", "e1">.as<"employee">(),
                   sqlgen::col<"name", "e2">.as<"manager">()) |
               sqlgen::left_join<Employee, "e2">(
                   sqlgen::col<"manager_id", "e1"> ==
                   sqlgen::col<"emp_id", "e2">) |
               sqlgen::to<std::vector<EmployeeManager>>;

  // Execute the query and return the result
  // Note: *query(conn) dereferences the Result<vector> to get the vector
  return *query(conn);
}

}  // namespace query_employee_hierarchy
