namespace query_high_value_orders {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct OrderView {
  static constexpr const char* tablename = "HighValueOrderView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  auto o_order_id = sqlgen::col<"order_id", "o">;
  auto o_customer_id = sqlgen::col<"customer_id", "o">;
  auto o_total_amount = sqlgen::col<"total_amount", "o">;
  auto o_order_date = sqlgen::col<"order_date", "o">;

  auto c_customer_id = sqlgen::col<"customer_id", "c">;
  auto c_name = sqlgen::col<"name", "c">;

  auto query = sqlgen::select_from<Order, "o">(o_order_id, c_name,
                                               o_total_amount, o_order_date) |
               sqlgen::inner_join<Customer, "c">(o_customer_id ==
                                                 c_customer_id) |
               sqlgen::where(o_total_amount > 1000) |
               sqlgen::order_by(o_total_amount.desc());

  return *(query | sqlgen::to<std::vector<OrderView>>)(conn);
}

}  // namespace query_high_value_orders
