std::vector<CategoryReport> query_product_sales_report() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // sqlgen's SelectFrom AST does not natively support a HAVING clause directly.
  // We achieve the equivalent of HAVING by wrapping the grouped query in a subquery 
  // and applying a WHERE clause to filter the aggregated results.
  auto query = select_from<Product, "p">(
                   "p"_c<"category">,
                   sum("s"_c<"quantity">) | as<"total_qty">,
                   sum("s"_c<"amount">) | as<"total_amt">)
               | inner_join<Sale, "s">("p"_c<"product_id"> == "s"_c<"product_id">)
               | group_by("p"_c<"category">);

  auto final_query = select_from<"q">(
                         query,
                         "q"_c<"category">,
                         "q"_c<"total_qty">,
                         "q"_c<"total_amt">)
                     | where("q"_c<"total_amt"> > 5000)
                     | to<std::vector<CategoryReport>>;

  auto conn = sqlite::connect("test_db.sqlite");
  return final_query(conn).value();
}

}  // namespace query_product_sales_report
