namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    // Connect to the SQLite database
    auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_res) {
        return {};
    }
    auto conn = conn_res.value();

    // Start with a base SELECT query
    std::string sql = "SELECT * FROM Book";
    bool has_where = false;

    // Helper lambda to dynamically append clauses
    auto add_clause = [&](const std::string& clause) {
        if (!has_where) {
            sql += " WHERE ";
            has_where = true;
        } else {
            sql += " AND ";
        }
        sql += clause;
    };

    // Add WHERE clauses dynamically based on non-null input parameters
    if (filters.title_keyword) {
        // Use LIKE for title search
        add_clause("title LIKE '%" + *filters.title_keyword + "%'");
    }
    if (filters.min_year) {
        // Use comparison operators for year
        add_clause("year >= " + std::to_string(*filters.min_year));
    }
    if (filters.genre) {
        // Exact match for genre
        add_clause("genre = '" + *filters.genre + "'");
    }
    if (filters.max_price) {
        // Use comparison operators for price
        add_clause("price <= " + std::to_string(*filters.max_price));
    }

    // Execute the dynamically constructed query
    auto res = conn->read<std::vector<Book>>(sql);
    if (res) {
        return res.value();
    }

    return {};
}

}  // namespace query_search_books_by_criteria
