#ifndef SQLGEN_UPDATE_HPP_
#define SQLGEN_UPDATE_HPP_

#include <rfl.hpp>
#include <type_traits>

#include "Ref.hpp"
#include "Result.hpp"
#include "is_connection.hpp"
