// Helper function to get the current timestamp in SQLite's expected format (UTC)
inline std::string get_current_timestamp() {
    auto now = std::chrono::system_clock::now();
    auto time = std::chrono::system_clock::to_time_t(now);
    std::tm tm_buf{};
#if defined(_WIN32) || defined(_WIN64)
    gmtime_s(&tm_buf, &time);
#else
    gmtime_r(&time, &tm_buf);
#endif
    std::stringstream ss;
    ss << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S");
    return ss.str();
}

bool soft_delete_records(const std::vector<int>& ids) {
    // If the list of IDs is empty, there is nothing to update.
    if (ids.empty()) {
        return true;
    }

    // Connect to the SQLite database and execute the update statement
    auto res = sqlgen::sqlite::connect("test_db.sqlite")
        .and_then([&](const auto& conn) {
            // Build the update statement
            auto update_stmt = sqlgen::update<Document>(
                sqlgen::col<"is_deleted">.set(1),
                sqlgen::col<"deleted_at">.set(get_current_timestamp())
            ) | sqlgen::where(sqlgen::col<"doc_id">.in(ids));

            // Execute the statement
            return update_stmt(conn);
        });

    // Return true if the connection and update were successful
    return static_cast<bool>(res);
}

}  // namespace soft_delete_records
