#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  // Connect to the SQLite database and begin a transaction
  auto tx_res = sqlgen::sqlite::connect("test_db.sqlite") | sqlgen::begin_transaction;
  if (!tx_res) {
    return false;
  }

  auto tx = *tx_res;

  // Deduct from sender, verifying sufficient funds
  auto res1 = tx->conn() | (
      sqlgen::update<Account>(sqlgen::col<"balance">.set(sqlgen::col<"balance"> - amount))
      | sqlgen::where(sqlgen::col<"account_id"> == from_account_id && sqlgen::col<"balance"> >= amount)
  );

  if (!res1) {
    return false; // Rollback happens automatically via RAII when `tx` goes out of scope
  }

  // Add to receiver
  auto res2 = tx->conn() | (
      sqlgen::update<Account>(sqlgen::col<"balance">.set(sqlgen::col<"balance"> + amount))
      | sqlgen::where(sqlgen::col<"account_id"> == to_account_id)
  );

  if (!res2) {
    return false;
  }

  // Commit the transaction
  auto commit_res = tx | sqlgen::commit;
  return bool(commit_res);
}

}  // namespace transaction_transfer_funds
