   // Connect to the SQLite database "test_db.sqlite"
   auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
   if (!conn_res) {
       return 0;
   }
   auto conn = *conn_res;

   int rows_affected = 0;

   // Task 2: Update 'pending' orders older than 7 days to 'expired'
   // We calculate the threshold date (now - 7 days) using std::chrono.
   // sqlgen handles the comparison between the DateTime column and the time_point.
   const auto seven_days_ago = std::chrono::system_clock::now() - std::chrono::hours(24 * 7);

   auto update_expired = sqlgen::update<Order>(
       "status"_c.set("expired")
   ) | sqlgen::where(
       "status"_c == "pending" && "order_date"_c < seven_days_ago
   );

   // Execute the first update and accumulate affected rows
   if (const auto res = update_expired(conn); res) {
       rows_affected += conn->changes();
   }

   // Task 3: Update 'shipped' orders to 'delivered' (simulated)
   auto update_delivered = sqlgen::update<Order>(
       "status"_c.set("delivered")
   ) | sqlgen::where(
       "status"_c == "shipped"
   );

   // Execute the second update and accumulate affected rows
   if (const auto res = update_delivered(conn); res) {
       rows_affected += conn->changes();
   }

   return rows_affected;
}

} // namespace update_order_status
