  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  // 1. Construct the SELECT query for the view
  auto query = sqlgen::select_from<Sale, "s">(
      sqlgen::col<"name", "p">.as<"product_name">(),
      sqlgen::sum(sqlgen::col<"quantity", "s">) | sqlgen::as<"total_quantity">,
      sqlgen::sum(sqlgen::col<"amount", "s">) | sqlgen::as<"total_revenue">
  )
  | sqlgen::inner_join<Product, "p">(sqlgen::col<"product_id", "s"> == sqlgen::col<"product_id", "p">)
  | sqlgen::group_by(sqlgen::col<"name", "p">);

  // 2. Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn.has_value()) {
    return false;
  }

  // 3. Handle DROP IF EXISTS manually for SQLite since it doesn't natively support CREATE OR REPLACE VIEW
  auto drop_res = conn.value()->execute("DROP VIEW IF EXISTS SalesSummary;");
  if (!drop_res.has_value()) {
    return false;
  }

  // 4. Execute create_as command
  auto action = sqlgen::create_as<SalesSummary>(query);
  auto res = action(conn.value());

  return res.has_value();
}

}  // namespace schema_create_view_sales_summary
