  // Create the table and insert the provided events
  conn->create_table<Event>();
  conn->insert(events);

  // Construct the query to analyze temporal data
  // We select specific columns and apply date/time functions, aliasing them to match the output struct
  auto query = sqlgen::select_from<Event>(
      "event_id"_c,
