  bool or_replace_;
};

template <class ContainerType>
Insert<ContainerType> insert_impl(const ContainerType& _data,
                                  bool _or_replace) {
  return Insert<ContainerType>{.data_ = _data, .or_replace_ = _or_replace};
}

template <class... Args>
auto insert(const Args&... args) {
