#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace upsert_inventory_items {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
};

/**
 * description: upsert_inventory_items.
 * This function demonstrates how to use upsert (insert or replace) statements in sqlgen write API.
 * It inserts or replaces the given inventory items in the Inventory table.
 */
bool upsert_inventory_items(const std::vector<Inventory>& items) {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // 1. Upsert items from vector input
  // The insert_or_replace function performs an INSERT OR REPLACE operation.
  // It takes the connection (or result of a connection) and the container of items.
  auto upsert_res = sqlgen::insert_or_replace(conn, items);

  // Check if the upsert operation was successful
  if (!upsert_res) {
    return false;
  }

  // 2. Read back items to verify
  // We use the connection returned from the upsert result to read the data back.
  // This verifies that the database is accessible and the operation succeeded.
  auto read_res = sqlgen::read<std::vector<Inventory>>(upsert_res);

  // Return true if the read operation was successful
  return (bool)read_res;
}

}  // namespace upsert_inventory_items
