Here is the complete code for the `analyze_social_network` function using the `sqlgen` library.

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>
#include <string>

namespace analyze_social_network {

// User Table Structure
struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::string email;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> join_date;
  std::optional<std::string> city;
};

// Friendship Table Structure
struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

// Result Structure
struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection> representing friend-of-friend relationships.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return {};
  }
  auto conn = *conn_res;

  // 2. Create tables for User and Friendship
  // We ignore the result here for simplicity, assuming table creation succeeds.
  (void)sqlgen::create_table<User>(conn);
  (void)sqlgen::create_table<Friendship>(conn);

  // 3. Insert data into tables
  for (const auto& user : users) {
    (void)conn->insert(user);
  }
  for (const auto& friendship : friendships) {
    (void)conn->insert(friendship);
  }

  // 4. Perform Query: Find friend-of-friend relationships
  // This query uses SELF-JOINs to find users connected through exactly one mutual friend.
  // Logic: u1 -> f1 (friendship) -> f2 (friendship) -> u2
  // We select the usernames of the two connected users.

  auto query = sqlgen::select_from<User, "u1">(
          "username"_c.of("u1") | sqlgen::as<"user1_name">,
          "username"_c.of("u2") | sqlgen::as<"user2_name">
      )
      | sqlgen::inner_join<Friendship, "f1">("user_id"_c.of("u1") == "user1_id"_c.of("f1"))
      | sqlgen::inner_join<Friendship, "f2">("user2_id"_c.of("f1") == "user1_id"_c.of("f2"))
      | sqlgen::inner_join<User, "u2">("user2_id"_c.of("f2") == "user_id"_c.of("u2"))
      | sqlgen::where("user_id"_c.of("u1") < "user_id"_c.of("u2"))
      | sqlgen::to<std::vector<FriendConnection>>();

  // Execute the query and return the result
  return query(conn).value_or(std::vector<FriendConnection>{});
}

}  // namespace analyze_social_network
