  // This query uses SELF-JOINs to find users connected through exactly one mutual friend.
  // Logic: u1 -> f1 (friendship) -> f2 (friendship) -> u2
  // We select the usernames of the two connected users.

  auto query = sqlgen::select_from<User, "u1">(
          "username"_c.of("u1") | sqlgen::as<"user1_name">,
          "username"_c.of("u2") | sqlgen::as<"user2_name">
      )
      | sqlgen::inner_join<Friendship, "f1">("user_id"_c.of("u1") == "user1_id"_c.of("f1"))
      | sqlgen::inner_join<Friendship, "f2">("user2_id"_c.of("f1") == "user1_id"_c.of("f2"))
      | sqlgen::inner_join<User, "u2">("user2_id"_c.of("f2") == "user_id"_c.of("u2"))
      | sqlgen::where("user_id"_c.of("u1") < "user_id"_c.of("u2"))
      | sqlgen::to<std::vector<FriendConnection>>();

  // Execute the query and return the result
  return query(conn).value_or(std::vector<FriendConnection>{});
}

}  // namespace analyze_social_network

