  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Define arithmetic expressions for the metrics.
  // Note: We use algebraic rearrangement because the library's operator overloads 
  // typically support (Col op Value) but not (Value op Col).
  // Expression: 1 - discount/100  <=>  discount * -0.01 + 1
  // Expression: 1 + tax/100       <=>  tax * 0.01 + 1

  auto gross_total_expr = "unit_price"_c * "quantity"_c;
  auto discount_factor = "discount_rate"_c * -0.01 + 1.0;
  auto tax_factor = "tax_rate"_c * 0.01 + 1.0;

  // Construct the query to calculate metrics
  auto query = sqlgen::select_from<OrderItem>(
      "item_id"_c,
      "order_id"_c,
      "product_id"_c,
      "unit_price"_c,
      "quantity"_c,
      "discount_rate"_c,
      "tax_rate"_c,

      // 1. Calculate total price (unit_price * quantity)
      gross_total_expr.as<"gross_total">(),

      // 2. Apply discount (total * (1 - discount_rate/100))
      (gross_total_expr * discount_factor).as<"discounted_total">(),

      // 3. Add tax (discounted_total * (1 + tax_rate/100))
      (gross_total_expr * discount_factor * tax_factor).as<"final_total">(),

      // 4. Calculate unit price per item (total / quantity)
      (gross_total_expr / "quantity"_c).as<"unit_cost">(),

      // 5. Determine quantity groups using modulo operation
      ("quantity"_c % 10).as<"quantity_group">(),

      // 6. Calculate profit margins (unit_price * 0.3)
      ("unit_price"_c * 0.3).as<"estimated_profit">()
  ) | sqlgen::to<std::vector<OrderMetrics>>();

  // Write the items to the database (creating the table if necessary) and execute the query.
  // conn | write(items) returns a Result<Ref<Connection>>, which is passed to the query functor.
  return query(conn | sqlgen::write(items)).value();
}

}  // namespace calculate_order_metrics
