/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // 2. Replace target token "foo" with "bar" in the content column
  // We use sqlgen::update to create the query and execute it immediately on the connection.
  // "content"_c refers to the column named "content".
  auto update_result = sqlgen::update<Note>(
      "content"_c.set(sqlgen::replace("content"_c, "foo", "bar")))(conn);

  // 3. Return updated view for verification
  // We read the data back from the table. Passing 'update_result' ensures we use the 
  // same connection (or result chain) after the update is complete.
  auto read_result = sqlgen::read<std::vector<Note>>(update_result);

  std::vector<UpdatedNote> result;

  // Check if the read operation was successful
  if (read_result) {
    const auto& notes = *read_result;
    result.reserve(notes.size());

    // Map the Note structs to UpdatedNote structs
    for (const auto& note : notes) {
      result.push_back({note.note_id, note.content});
    }
  }

  return result;
}

}  // namespace replace_text_in_notes
