 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
inline bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.value();

  // 2. Drop the table if it exists to ensure a clean state
  auto drop_res = conn->execute("DROP TABLE IF EXISTS Inventory;");
  if (!drop_res) {
    return false;
  }

  // 3. Bulk write records (this will automatically create the table)
  auto write_res = sqlgen::write(conn, items);
  if (!write_res) {
    return false;
  }

  // 4. Read records with filters and ordering
  auto query = sqlgen::read<std::vector<Inventory>>
             | sqlgen::where("quantity"_c > 50)
             | sqlgen::order_by("quantity"_c.desc());

  auto read_res = query(conn);
  if (!read_res) {
    return false;
  }

  // 5. Return true if at least one item is found
  return !read_res.value().empty();
}

}  // namespace inventory_bulk_write_and_read
