```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  // Initialize with sqlgen::cascade to enable ON DELETE CASCADE constraint
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id =
      sqlgen::ForeignKey<int, Parent, "parent_id">() | sqlgen::cascade;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = *conn_res;

  // Enable foreign keys (required for SQLite cascade delete to work)
  conn->execute("PRAGMA foreign_keys = ON;");

  // 2. Create Tables
  // Drop existing tables to ensure a clean state for the demo
  conn->execute("DROP TABLE IF EXISTS Child;");
  conn->execute("DROP TABLE IF EXISTS Parent;");

  if (!sqlgen::create_table<Parent>(conn)) {
    return false;
  }
  if (!sqlgen::create_table<Child>(conn)) {
    return false;
  }

  // 3. Insert parent and child records
  Parent p{1, "Parent1"};
  Child c{1, 1, "Child1"};

  if (!sqlgen::insert(conn, p)) {
    return false;
  }
  if (!sqlgen::insert(conn, c)) {
    return false;
  }

  // 4. Delete parent
  // This should automatically delete the related child record due to cascade
  auto delete_res =
      (sqlgen::delete_from<Parent> | sqlgen::where("parent_id"_c == 1))(conn);
  if (!delete_res) {
    return false;
  }

  // 5. Verify child deletion
  // We verify by attempting to insert the same child record again.
  // If cascade delete worked, the child row is gone, so the insert will succeed.
  // If cascade delete failed, the child row still exists (PK 1), so the insert
  // will fail with a constraint violation.
  auto verify_res = sqlgen::insert(conn, c);

  return (bool)verify_res;
}

}  // namespace cascade_delete_demo
