  // Filtering rows where 'bio' is missing (IS NULL) but 'avatar_url' is present (IS NOT NULL)
  auto query = sqlgen::read<std::vector<Profile>> |
               sqlgen::where(sqlgen::col<"bio">.is_null() &&
                             sqlgen::col<"avatar_url">.is_not_null());

  // 3. Execute the query
  auto profiles_result = query(conn);

  std::vector<Result> filtered_datasets;

  // 4. Map the results to the expected output format
  if (profiles_result.has_value()) {
    for (const auto& profile : profiles_result.value()) {
      filtered_datasets.push_back({
          profile.profile_id,
          profile.display_name
      });
    }
  }

  return filtered_datasets;
