#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <string>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }

  // 2. Create Account table
  // The create_table function returns a Result<Ref<Connection>>, which allows chaining or error checking.
  auto create_res = sqlgen::create_table<Account>(conn_res);
  if (!create_res) {
    return false;
  }

  // 3. Insert initial data to be updated
  std::vector<Account> accounts = {{1, 100.0, "pending"}};
  auto write_res = sqlgen::write(create_res, accounts);
  if (!write_res) {
    return false;
  }

  // 4. Update balances and statuses using set(...)
  // We construct an update operation that sets 'balance' to 500.0 and 'status' to "active".
  // We then apply a WHERE clause to target the account with account_id = 1.
  auto update_op = sqlgen::update<Account>(
      "balance"_c.set(500.0),
      "status"_c.set("active")
  ) | sqlgen::where("account_id"_c == 1);

  // Execute the update operation
  auto update_res = update_op(write_res);
  if (!update_res) {
    return false;
  }

  // 5. Verify changes persisted
  // Read back the data from the database to verify the update.
  auto read_res = sqlgen::read<Account>(update_res);
  if (!read_res) {
    return false;
  }

  // Iterate through the results to find the updated account
  for (const auto& acc : *read_res) {
    if (acc.account_id == 1) {
      if (acc.balance == 500.0 && acc.status == "active") {
        return true;
      }
    }
  }

  return false;
}

}  // namespace update_set_operations
