}

template <class Connection>
  requires is_connection<Connection>
Result<Ref<Connection>> exec(const Result<Ref<Connection>>& _res,
                             const std::string& _sql) {
  return _res.and_then([&](const auto& _conn) { return exec(_conn, _sql); });
}

