std::vector<OrderSummary> create_view_order_summary() {
    // 1. Connect to the SQLite database
    auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_res.has_value()) {
        return {};
    }
    auto conn = conn_res.value();

    // Drop the view if it already exists to ensure a fresh creation
    conn->execute("DROP VIEW IF EXISTS OrderSummaryView;");

    // 2. Create the view using raw SQL to perfectly match the reference SQL statement
    std::string create_view_sql = 
        "CREATE VIEW OrderSummaryView AS\n"
        "SELECT o.order_id, o.customer, SUM(oi.unit_price*oi.quantity) as total\n"
        "FROM Order o INNER JOIN OrderItem oi ON o.order_id=oi.order_id\n"
        "GROUP BY o.order_id, o.customer;";

